var download = new Download();
EventHandler<ProgressEventArgs> handler = OnProgress;
download.ProgressChanged += handler;
download.Report(50);
download.ProgressChanged -= handler;

static void OnProgress(object? sender, ProgressEventArgs e)
    => Console.WriteLine($"{e.Percent}%");

sealed class Download
{
    public event EventHandler<ProgressEventArgs>? ProgressChanged;
    public void Report(int percent)
        => ProgressChanged?.Invoke(this, new ProgressEventArgs(percent));
}

sealed class ProgressEventArgs(int percent) : EventArgs
{
    public int Percent { get; } = percent;
}

